import sqlite3

from agents import function_tool

_DB = "/srv/recruiting/ats.db"


@function_tool
def get_applicant_pipeline_status(applicant_id: int) -> dict:
    q = (
        "SELECT a.name, j.title, a.stage, a.updated_at "
        "FROM applicants a JOIN jobs j ON j.id = a.job_id WHERE a.id = ?"
    )
    con = sqlite3.connect(f"file:{_DB}?mode=ro", uri=True)
    try:
        r = con.execute(q, (applicant_id,)).fetchone()
    finally:
        con.close()
    if r is None:
        return {"found": False, "applicant_id": applicant_id}
    return {"found": True, "name": r[0], "job": r[1], "stage": r[2], "updated_at": r[3]}

import subprocess
import sys
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("recruiting")

_PARSER = "/opt/recruiting/tools/parse_resumes.py"


@mcp.tool()
def run_resume_parser_batch(job_id: int, resume_dir: str, output_path: str, timeout_seconds: int = 300) -> dict:
    if job_id <= 0:
        return {"ok": False, "error": "job_id must be a positive integer"}
    if timeout_seconds < 1 or timeout_seconds > 3600:
        return {"ok": False, "error": "timeout_seconds must be between 1 and 3600"}
    src = Path(resume_dir)
    if not src.is_dir():
        return {"ok": False, "error": f"Resume directory not found: {resume_dir}"}
    out = Path(output_path)
    if out.suffix != ".json":
        return {"ok": False, "error": "output_path must end with .json"}
    if not out.parent.is_dir():
        return {"ok": False, "error": f"Output directory does not exist: {out.parent}"}

    cmd = [
        sys.executable,
        _PARSER,
        "--job-id", str(job_id),
        "--input", str(src),
        "--output", str(out),
    ]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": f"Parser timed out after {timeout_seconds} seconds"}

    return {
        "ok": proc.returncode == 0,
        "exit_code": proc.returncode,
        "stdout": proc.stdout[-2000:],
        "stderr": proc.stderr[-2000:],
    }

import sqlite3
from contextlib import closing

_DB = "/srv/recruiting/ats.db"


def archive_rejected_applicant(applicant_id: int) -> dict:
    with closing(sqlite3.connect(_DB)) as con:
        with con:
            row = con.execute(
                "SELECT id FROM applicants WHERE id = ? AND stage = 'rejected'",
                (applicant_id,),
            ).fetchone()
            if row is None:
                return {"archived": False, "reason": "No rejected applicant with that ID"}
            con.execute(
                "INSERT INTO archived_applicants (id, name, email, job_id, stage, updated_at) "
                "SELECT id, name, email, job_id, stage, updated_at FROM applicants WHERE id = ?",
                (applicant_id,),
            )
            con.execute("DELETE FROM applicants WHERE id = ?", (applicant_id,))
    return {"archived": True, "applicant_id": applicant_id}
